@extends('layouts.app') @section('page-title','New Purchase') @section('content')<form method="POST" action="{{ route('purchases.store') }}" id="purchaseForm">@csrf<div class="card p-3 mb-3"><div class="row g-3"><div class="col-md-6"><label class="form-label">Supplier</label><select name="supplier_id" class="form-select"><option value="">Select supplier</option>@foreach($suppliers as $s)<option value="{{ $s->id }}">{{ $s->name }}</option>@endforeach</select></div><div class="col-md-6"><label class="form-label">Business Owner</label><select name="business_unit_id" class="form-select"><option value="">General / Shared</option>@foreach($businessUnits as $b)<option value="{{ $b->id }}">{{ $b->name }}</option>@endforeach</select></div></div></div><div class="card p-3"><div class="row g-2 mb-3"><div class="col-md-8"><label class="form-label">Product</label><select id="product" class="form-select"><option value="">Select product</option>@foreach($products as $p)<option value="{{ $p->id }}" data-name="{{ $p->name }}" data-cost="{{ $p->purchase_price }}">{{ $p->name }} ({{ $p->baseUnit->short_name }})</option>@endforeach</select></div><div class="col-md-2"><label class="form-label">Qty</label><input id="qty" class="form-control" type="number" step="0.001" value="1"></div><div class="col-md-2"><label class="form-label">Unit Cost</label><input id="cost" class="form-control" type="number" step="0.01" value="0"></div></div><button type="button" class="btn btn-outline-primary mb-3" id="add">Add Item</button><div id="items"></div><div class="row mt-3"><div class="col-md-6"><label class="form-label">Paid Amount</label><input name="paid" type="number" step="0.01" min="0" value="0" class="form-control"></div><div class="col-md-6"><label class="form-label">Notes</label><input name="notes" class="form-control"></div></div><button class="btn btn-success mt-3">Save Purchase & Add Stock</button></div></form>@endsection
@push('scripts')<script>let rows=[];document.getElementById('product').addEventListener('change',e=>{const o=e.target.selectedOptions[0];document.getElementById('cost').value=o.dataset.cost||0});document.getElementById('add').onclick=()=>{const s=document.getElementById('product'),o=s.selectedOptions[0];if(!s.value)return alert('Select product');rows.push({id:s.value,name:o.dataset.name,qty:Number(document.getElementById('qty').value),cost:Number(document.getElementById('cost').value)});draw()};function draw(){document.getElementById('items').innerHTML=rows.map((r,i)=>`<div class="d-flex justify-content-between border-bottom py-2"><span>${r.name} — ${r.qty} × ${r.cost}</span><button type="button" class="btn btn-sm btn-outline-danger" onclick="rows.splice(${i},1);draw()">Remove</button><input type="hidden" name="items[${i}][product_id]" value="${r.id}"><input type="hidden" name="items[${i}][quantity]" value="${r.qty}"><input type="hidden" name="items[${i}][unit_cost]" value="${r.cost}"></div>`).join('')}</script>@endpush
